"""Parsing of cold chain sensor logs and detection of temperature excursions."""

from dataclasses import dataclass
from datetime import datetime
import logging

logger = logging.getLogger(__name__)

MIN_SAFE_TEMP_C = 2.0
MAX_SAFE_TEMP_C = 8.0


class SensorDataError(Exception):
    """Raised when a shipment's sensor log cannot be evaluated at all."""


class ExcursionError(Exception):
    """Raised when a shipment spent too long outside the safe temperature band."""


@dataclass
class SensorReading:
    timestamp: datetime
    temp_c: float


def load_readings(log_path):
    readings = []
    try:
        handle = open(log_path, "r")
    except FileNotFoundError as exc:
        raise SensorDataError(f"no sensor log found at {log_path}") from exc

    with handle:
        for lineno, line in enumerate(handle, start=1):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(",")
            if len(parts) != 2:
                logger.warning("skipping malformed line %d in %s", lineno, log_path)
                continue
            ts_raw, temp_raw = parts
            try:
                ts = datetime.fromisoformat(ts_raw)
                temp_c = float(temp_raw)
            except ValueError:
                logger.warning("skipping unparsable reading on line %d in %s", lineno, log_path)
                continue
            readings.append(SensorReading(timestamp=ts, temp_c=temp_c))

    return readings


def _excursion_minutes(readings):
    """Return the duration, in minutes, of the longest unbroken run outside the safe band."""
    longest = 0.0
    current_start = None
    previous = None

    for reading in readings:
        out_of_band = reading.temp_c < MIN_SAFE_TEMP_C or reading.temp_c > MAX_SAFE_TEMP_C
        if out_of_band:
            if current_start is None:
                current_start = reading.timestamp
            previous = reading.timestamp
        else:
            if current_start is not None:
                longest = max(longest, (previous - current_start).total_seconds() / 60)
            current_start = None
            previous = None

    if current_start is not None:
        longest = max(longest, (previous - current_start).total_seconds() / 60)

    return longest


def evaluate_shipment(readings, max_allowed_minutes):
    if not readings:
        raise SensorDataError("no usable temperature readings recovered from log")

    duration = _excursion_minutes(readings)
    if duration > max_allowed_minutes:
        raise ExcursionError(
            f"temperature excursion lasted {duration:.1f} min, "
            f"exceeding the {max_allowed_minutes} min tolerance"
        )

    return duration
